import{_ as a,o as t,a as o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Upgrade Guide","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/upgrade-guide.md","filePath":"getting-started/upgrade-guide.md","lastUpdated":1789464754000}'),s={name:"getting-started/upgrade-guide.md"};function n(i,e,d,c,h,l){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h1><p>Bagisto is a complete Laravel application, not a package inside one. Upgrading means bringing your copy of the application files up to the new release, reconciling the files you changed, installing the new dependencies and running the migrations. The Bagisto repository keeps the full procedure and every breaking change in <code>UPGRADE.md</code>; this page tells you which copy to read, what to prepare, and which changes reach your own packages and themes.</p><div class="tip custom-block"><p class="custom-block-title">Full Upgrade Procedure</p><p>Follow <a href="https://github.com/bagisto/bagisto/blob/master/UPGRADE.md" target="_blank" rel="noreferrer"><code>UPGRADE.md</code></a> to upgrade from 2.4 to 2.5. It has the commands, the configuration files to bring across, and the code changes for each breaking change.</p></div><h2 id="which-document-to-read" tabindex="-1">Which Document to Read <a class="header-anchor" href="#which-document-to-read" aria-label="Permalink to &quot;Which Document to Read&quot;">​</a></h2><p>Each <code>UPGRADE.md</code> covers one release line. From an older release, work through them in order.</p><table tabindex="0"><thead><tr><th>Upgrading</th><th>Read</th></tr></thead><tbody><tr><td>2.4 to 2.5</td><td><a href="https://github.com/bagisto/bagisto/blob/master/UPGRADE.md" target="_blank" rel="noreferrer"><code>UPGRADE.md</code> on <code>master</code></a></td></tr><tr><td>2.3 to 2.4</td><td><a href="https://github.com/bagisto/bagisto/blob/2.4/UPGRADE.md" target="_blank" rel="noreferrer"><code>UPGRADE.md</code> on the <code>2.4</code> branch</a></td></tr><tr><td>2.2 to 2.3</td><td><a href="https://github.com/bagisto/bagisto/blob/2.3/UPGRADE.md" target="_blank" rel="noreferrer"><code>UPGRADE.md</code> on the <code>2.3</code> branch</a></td></tr><tr><td>2.1 to 2.2</td><td><a href="https://github.com/bagisto/bagisto/blob/2.2/UPGRADE.md" target="_blank" rel="noreferrer"><code>UPGRADE.md</code> on the <code>2.2</code> branch</a></td></tr></tbody></table><p>The <code>CHANGELOG.md</code> on the same branch lists what changed in each release of that line.</p><h2 id="before-you-upgrade" tabindex="-1">Before You Upgrade <a class="header-anchor" href="#before-you-upgrade" aria-label="Permalink to &quot;Before You Upgrade&quot;">​</a></h2><ul><li><strong>Back up the database and <code>storage/</code>.</strong> Some migrations rewrite existing rows, and their <code>down()</code> methods don&#39;t restore the old values.</li><li><strong>Check that <code>APP_URL</code> is the live store&#39;s address.</strong> A migration keeps theme section links portable only for links on that host.</li><li><strong>Rehearse on a copy of the store</strong>, with a copy of its data, before you upgrade production.</li><li><strong>Plan for maintenance mode</strong> while the migrations run; see <a href="https://github.com/bagisto/bagisto/blob/master/UPGRADE.md#before-you-start" target="_blank" rel="noreferrer">Before You Start</a>.</li><li><strong>List your custom packages and themes</strong>, and check each one against the changes below. Edits inside <code>packages/Webkul/</code> or <code>vendor/</code> are overwritten, so move them into a package, a theme or an event listener first; see <a href="./../architecture/overview.html#extension-points-at-a-glance">Extension Points at a Glance</a>.</li></ul><div class="danger custom-block"><p class="custom-block-title">Never Run the Installer on an Existing Store</p><p><code>php artisan bagisto:install</code> runs <code>db:wipe</code> and then <code>migrate:fresh</code>, which destroys your data. An upgrade only runs <code>php artisan migrate</code>.</p></div><p><a id="upgrading-from-v2-4-to-v2-5"></a></p><h2 id="changes-that-affect-packages-and-themes" tabindex="-1">Changes That Affect Packages and Themes <a class="header-anchor" href="#changes-that-affect-packages-and-themes" aria-label="Permalink to &quot;Changes That Affect Packages and Themes&quot;">​</a></h2><p>These 2.5 changes most often need work in a custom package or theme; <code>UPGRADE.md</code> has the migration steps.</p><ul><li><strong>Laravel 13 and PHP 8.4.</strong> Several dependencies moved to a new major version, and PHP 8.4 deprecates implicitly nullable parameters, so write <code>?string $locale = null</code>. See <a href="./before-you-start.html#system-requirements">System Requirements</a>.</li><li><strong>Search engines.</strong> Search runs through <code>SearchEngineManager</code>: the Elasticsearch repository and jobs were replaced, the settings moved to <code>search_engines.*</code> codes, and <code>indexer:index --type=elastic</code> is now <code>--type=search</code>. See <a href="./../advanced/search-engines.html">Search Engines</a>. A store with Elasticsearch credentials in <code>.env</code> must re-enter them in the admin after migrating; see <a href="./../performance/configure-elasticsearch.html#things-to-watch">Configure Elasticsearch</a>.</li><li><strong>Relocated configuration codes.</strong> <code>sales.checkout.my_cart.summary</code> is now <code>sales.checkout.mini_cart.summary</code>, and <code>catalog.products.storefront.buy_now_button_display</code> is now <code>catalog.products.product_view_page.buy_now_button_display</code>. A migration moves stored values, but code reading the old codes must change; see <a href="https://github.com/bagisto/bagisto/blob/master/UPGRADE.md#relocated-configuration-codes" target="_blank" rel="noreferrer">Relocated Configuration Codes</a>.</li><li><strong>Tailwind CSS 4.</strong> A theme or package with its own Tailwind build moves to the <code>@tailwindcss/vite</code> plugin and configures Tailwind in <code>app.css</code>. Some icon classes were renamed or removed. See <a href="./../theme-development/vite-powered-theme-assets.html">Vite-Powered Theme Assets</a>.</li><li><strong>Images.</strong> <code>image_manager()</code> returns Laravel&#39;s <code>Illuminate\\Image\\ImageManager</code>, and an image template is a class whose <code>applyFilter()</code> takes and returns <code>Illuminate\\Image\\Image</code>. See <a href="./../theme-development/image-cache-templates.html">Image Cache</a>.</li><li><strong>Theme section media.</strong> Sections store uploads as bare paths (<code>themes/...</code>), so an overridden section view builds its URLs with <code>bagisto_theme_storage()</code>. See <a href="./../theme-development/theme-sections.html">Theme Sections</a>.</li><li><strong>PostgreSQL.</strong> Custom queries must run on MySQL, MariaDB and PostgreSQL, for example with <code>db_grammar()-&gt;caseInsensitiveLike()</code> instead of <code>&#39;like&#39;</code>. See <a href="./../advanced/database-compatibility.html">Database Compatibility</a>.</li><li><strong>Configuration files.</strong> The upgrade doesn&#39;t touch your <code>config/</code> directory. Take <code>config/responsecache.php</code> from the release, and replace <code>config/image.php</code> with <code>config/images.php</code>; the <a href="https://github.com/bagisto/bagisto/blob/master/UPGRADE.md#configuration-files-you-maintain-yourself" target="_blank" rel="noreferrer">configuration files section</a> of <code>UPGRADE.md</code> lists the rest.</li><li><strong>Omnibus registration.</strong> Merge the new <code>Webkul\\Omnibus</code> entries into your <code>composer.json</code>, <code>bootstrap/providers.php</code> and <code>config/concord.php</code>; see <a href="https://github.com/bagisto/bagisto/blob/master/UPGRADE.md#the-omnibus-package" target="_blank" rel="noreferrer">The Omnibus Package</a>.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./deployment.html">Deployment</a>: what a production server needs after the upgrade.</li><li><a href="./../advanced/common-pitfalls.html">Common Pitfalls</a>: the symptom, cause and fix for problems developers hit again and again, such as a PHP version error.</li></ul>',16)]))}const p=a(s,[["render",n]]);export{m as __pageData,p as default};
